SELECT jsonb_build_object('work',count(*),'pending_zero_fence_attempt_null_lease_effect',coalesce(bool_and(w.outbox_message_id='6be93914-5cc2-5cc0-a5b6-0906f8b4add1'::uuid AND w.handler_name='assignDefaultFreeTrack.v1' AND w.semantic_work_key='customer_buyer_profile/cdfa190f-3235-5c98-b217-bf27a5d03d66/default-free-enrollment/v1' AND w.state='pending' AND w.fence=0 AND w.attempt_count=0 AND w.lease_token_hash IS NULL AND w.lease_expires_at IS NULL AND w.effect_receipt_id IS NULL),false),'not_before_null',coalesce(bool_and(w.next_attempt_at IS NULL),false),'not_before_future',coalesce(bool_and(w.next_attempt_at>clock_timestamp() AND w.next_attempt_at<=clock_timestamp()+interval '120 seconds'),false),'identity_sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(w)-'next_attempt_at'-'mutation_transaction_id' ORDER BY w.id),'[]'::jsonb)::text,'UTF8')),'hex')) FROM platform.runtime_work_item w WHERE w.id='530db9d1-b945-53ec-bb0c-6d91c914b5fc';
